def comps(mask):
    seen=set(); sizes=[]
    for r in range(10):
      for c in range(10):
        if mask[r,c] and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); n=0
          while stack:
            rr,cc=stack.pop(); n+=1
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
              nr,nc=rr+dr,cc+dc
              if 0<=nr<10 and 0<=nc<10 and mask[nr,nc] and (nr,nc) not in seen:
                seen.add((nr,nc)); stack.append((nr,nc))
          sizes.append(n)
    return sizes
